param([ValidateSet('build','test')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-strong-float-replay-20260914';$seed='D:\projects\AIMA-public-matrix-algorithm-20260914';$sha='57ddfe994da5b5f1f88dd9fde96f8357c50df7f3';$bundle='D:\projects\strong-float-replay-57ddfe9.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '16ef201855b11f2d6e7fbaaef16643e6db1dde0e315bf4125b0f8f35cde1eddf'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){& git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'};& git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\strong-float-replay';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\strong_float_replay_selftest.cpp';$exe=Join-Path $build 'strong-float-replay.exe';$provenance=Join-Path $build 'build-provenance.json'
$sourceFiles=@($source,(Join-Path $repo 'tests\native\strong_float_replay_cases.h'));$sourceFiles+=@(Get-ChildItem (Join-Path $repo 'native\providers\moe_accumulator') -Filter '*.h' -File|ForEach-Object {$_.FullName})
$sourceInputs=@();foreach($file in $sourceFiles){$sourceInputs+=@{file=$file;sha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; generated dense/MoE reduction shapes';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;purpose='Validate row-certified scalar replay with BF16 exponent84..174 or zero and K<=4096. Remove per-group range checks and original-product backups only for certified rows. Every ordered K16 endpoint is compared with independent CPU original integer arithmetic for4/8/16 lanes and1/4/8 staging groups. Include cancellation, signed zeros, exceptional rows, K16/272/2048/4096, overcapacity K4112 original fallback and all guards. Product dispatch remains unchanged.'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe';$spec.arguments=@('-std=c++17','-O3','-DQRT_SM121_DPP_REDUCTION=1','-DQRT_SM121_COMPACT_NORMALIZE=1','--offload-arch=gfx1151',$source,'-o',$exe);$timeout=120
}else{
 $meta=[IO.File]::ReadAllText($provenance)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $meta.executable.sha256){throw 'Executable provenance mismatch'}
 $spec.build_provenance_sha256=(Get-FileHash $provenance -Algorithm SHA256).Hash.ToLowerInvariant();$spec.executable=$exe;$timeout=90
}
$specPath=Join-Path $build ($Action+'-spec-r1.json');$out=Join-Path $repo ('build\strong-float-replay-'+$Action+'-r1')
if((Test-Path $specPath) -or (Test-Path $out)){throw 'Evidence exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native subgroup diagnostic failed'}
if($Action -eq 'build'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText($provenance,($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 if($reports.Count -ne 30){throw 'Incomplete subgroup diagnostic'}
 foreach($report in $reports){if($report.raw_bit_mismatches -ne 0 -or -not $report.redzones_pass -or -not $report.immutable_inputs){throw 'Subgroup arithmetic or memory failure'}}
}
